-- ----------------------------
-- Table structure for ai_agent_runs
-- ----------------------------
DROP TABLE IF EXISTS "public"."ai_agent_runs";
CREATE TABLE "public"."ai_agent_runs" (
  "id" int8 NOT NULL DEFAULT nextval('ai_agent_runs_id_seq'::regclass),
  "uuid" varchar(32) COLLATE "pg_catalog"."default" NOT NULL,
  "conversation_id" int8,
  "message_id" int8,
  "agent_id" int8,
  "agent_version_id" int8,
  "run_type" varchar(32) COLLATE "pg_catalog"."default" DEFAULT 'chat'::character varying,
  "status" varchar(16) COLLATE "pg_catalog"."default" NOT NULL DEFAULT 'queued'::character varying,
  "idempotency_key" varchar(100) COLLATE "pg_catalog"."default",
  "model" varchar(64) COLLATE "pg_catalog"."default",
  "provider" varchar(32) COLLATE "pg_catalog"."default",
  "input_tokens" int4 DEFAULT 0,
  "output_tokens" int4 DEFAULT 0,
  "total_tokens" int4 DEFAULT 0,
  "latency_ms" int4,
  "started_at" timestamp(6),
  "completed_at" timestamp(6),
  "error_code" varchar(32) COLLATE "pg_catalog"."default",
  "error_message" text COLLATE "pg_catalog"."default",
  "metadata" jsonb,
  "created_at" timestamp(6) DEFAULT now()
)
;
COMMENT ON COLUMN "public"."ai_agent_runs"."id" IS '自增 ID';
COMMENT ON COLUMN "public"."ai_agent_runs"."uuid" IS '对外 Run ID';
COMMENT ON COLUMN "public"."ai_agent_runs"."conversation_id" IS '所属会话';
COMMENT ON COLUMN "public"."ai_agent_runs"."message_id" IS '触发 Run 的消息';
COMMENT ON COLUMN "public"."ai_agent_runs"."agent_id" IS '执行 Agent';
COMMENT ON COLUMN "public"."ai_agent_runs"."agent_version_id" IS 'Agent 版本快照';
COMMENT ON COLUMN "public"."ai_agent_runs"."run_type" IS '类型（chat/trunk_search/gap_search/branch/network）';
COMMENT ON COLUMN "public"."ai_agent_runs"."status" IS '状态（queued/running/waiting/completed/failed/cancelled/timeout）';
COMMENT ON COLUMN "public"."ai_agent_runs"."idempotency_key" IS '幂等键（防重复提交，UNIQUE）';
COMMENT ON COLUMN "public"."ai_agent_runs"."model" IS '主模型（多模型编排时记录最终模型）';
COMMENT ON COLUMN "public"."ai_agent_runs"."provider" IS '模型提供商';
COMMENT ON COLUMN "public"."ai_agent_runs"."input_tokens" IS '输入 Token';
COMMENT ON COLUMN "public"."ai_agent_runs"."output_tokens" IS '输出 Token';
COMMENT ON COLUMN "public"."ai_agent_runs"."total_tokens" IS '总 Token';
COMMENT ON COLUMN "public"."ai_agent_runs"."latency_ms" IS '总耗时（毫秒）';
COMMENT ON COLUMN "public"."ai_agent_runs"."started_at" IS '开始时间';
COMMENT ON COLUMN "public"."ai_agent_runs"."completed_at" IS '完成时间';
COMMENT ON COLUMN "public"."ai_agent_runs"."error_code" IS '错误码';
COMMENT ON COLUMN "public"."ai_agent_runs"."error_message" IS '错误信息';
COMMENT ON COLUMN "public"."ai_agent_runs"."metadata" IS '附加元数据（探针/分类/范围等）';
COMMENT ON COLUMN "public"."ai_agent_runs"."created_at" IS '创建时间';
COMMENT ON TABLE "public"."ai_agent_runs" IS 'Agent 执行记录：一次用户请求的完整执行过程（可观测/可重试）';

-- ----------------------------
-- Records of ai_agent_runs
-- ----------------------------

-- ----------------------------
-- Table structure for ai_agent_steps
-- ----------------------------
DROP TABLE IF EXISTS "public"."ai_agent_steps";
CREATE TABLE "public"."ai_agent_steps" (
  "id" int8 NOT NULL DEFAULT nextval('ai_agent_steps_id_seq'::regclass),
  "run_id" int8 NOT NULL,
  "step_index" int4 NOT NULL,
  "step_type" varchar(32) COLLATE "pg_catalog"."default" NOT NULL,
  "step_name" varchar(64) COLLATE "pg_catalog"."default",
  "input" jsonb,
  "output" jsonb,
  "output_embedding" "public"."vector",
  "status" varchar(16) COLLATE "pg_catalog"."default" NOT NULL DEFAULT 'running'::character varying,
  "model" varchar(64) COLLATE "pg_catalog"."default",
  "provider" varchar(32) COLLATE "pg_catalog"."default",
  "input_tokens" int4 DEFAULT 0,
  "output_tokens" int4 DEFAULT 0,
  "latency_ms" int4,
  "started_at" timestamp(6),
  "completed_at" timestamp(6),
  "error_code" varchar(32) COLLATE "pg_catalog"."default",
  "error_message" text COLLATE "pg_catalog"."default",
  "metadata" jsonb
)
;
COMMENT ON COLUMN "public"."ai_agent_steps"."id" IS '自增 ID';
COMMENT ON COLUMN "public"."ai_agent_steps"."run_id" IS '所属 Run';
COMMENT ON COLUMN "public"."ai_agent_steps"."step_index" IS '步骤序号（1 起）';
COMMENT ON COLUMN "public"."ai_agent_steps"."step_type" IS '步骤类型（intent/decompose/retrieval/rerank/skeleton/probe/llm/tool）';
COMMENT ON COLUMN "public"."ai_agent_steps"."step_name" IS '步骤名称（人类可读，如 OpenAlex 召回）';
COMMENT ON COLUMN "public"."ai_agent_steps"."input" IS '步骤输入（脱敏后）';
COMMENT ON COLUMN "public"."ai_agent_steps"."output" IS '步骤输出摘要（不存全量）';
COMMENT ON COLUMN "public"."ai_agent_steps"."output_embedding" IS '步骤输出语义向量 1024 维（记忆检索，可空）';
COMMENT ON COLUMN "public"."ai_agent_steps"."status" IS '状态（running/completed/failed/skipped）';
COMMENT ON COLUMN "public"."ai_agent_steps"."model" IS '该步骤使用的模型';
COMMENT ON COLUMN "public"."ai_agent_steps"."provider" IS '该步骤模型提供商';
COMMENT ON COLUMN "public"."ai_agent_steps"."input_tokens" IS '该步骤输入 Token';
COMMENT ON COLUMN "public"."ai_agent_steps"."output_tokens" IS '该步骤输出 Token';
COMMENT ON COLUMN "public"."ai_agent_steps"."latency_ms" IS '该步骤耗时（毫秒）';
COMMENT ON COLUMN "public"."ai_agent_steps"."started_at" IS '开始时间';
COMMENT ON COLUMN "public"."ai_agent_steps"."completed_at" IS '完成时间';
COMMENT ON COLUMN "public"."ai_agent_steps"."error_code" IS '错误码';
COMMENT ON COLUMN "public"."ai_agent_steps"."error_message" IS '错误信息';
COMMENT ON COLUMN "public"."ai_agent_steps"."metadata" IS '附加元数据（检索数量/分数分布等）';
COMMENT ON TABLE "public"."ai_agent_steps" IS 'Agent 步骤：Run 内每个执行步骤（可观测/调试/重试）';

-- ----------------------------
-- Records of ai_agent_steps
-- ----------------------------

-- ----------------------------
-- Table structure for ai_agent_versions
-- ----------------------------
DROP TABLE IF EXISTS "public"."ai_agent_versions";
CREATE TABLE "public"."ai_agent_versions" (
  "id" int8 NOT NULL DEFAULT nextval('ai_agent_versions_id_seq'::regclass),
  "agent_id" int8 NOT NULL,
  "version" int4 NOT NULL,
  "system_prompt" text COLLATE "pg_catalog"."default",
  "model" varchar(64) COLLATE "pg_catalog"."default",
  "provider" varchar(32) COLLATE "pg_catalog"."default",
  "config" jsonb,
  "status" int2 DEFAULT 0,
  "created_at" timestamp(6) DEFAULT now()
)
;
COMMENT ON COLUMN "public"."ai_agent_versions"."id" IS '版本 ID';
COMMENT ON COLUMN "public"."ai_agent_versions"."agent_id" IS '所属 Agent';
COMMENT ON COLUMN "public"."ai_agent_versions"."version" IS '版本号（自增）';
COMMENT ON COLUMN "public"."ai_agent_versions"."system_prompt" IS '系统提示词（不可变快照）';
COMMENT ON COLUMN "public"."ai_agent_versions"."model" IS '默认模型';
COMMENT ON COLUMN "public"."ai_agent_versions"."provider" IS '模型提供商（deepseek/openai 等）';
COMMENT ON COLUMN "public"."ai_agent_versions"."config" IS '版本配置（temperature/max_tokens/工具列表等）';
COMMENT ON COLUMN "public"."ai_agent_versions"."status" IS '状态（0=草稿 1=已发布 2=已下线）';
COMMENT ON COLUMN "public"."ai_agent_versions"."created_at" IS '创建时间';
COMMENT ON TABLE "public"."ai_agent_versions" IS 'Agent 版本：system_prompt/模型配置不可变快照（升级不影响旧会话）';

-- ----------------------------
-- Records of ai_agent_versions
-- ----------------------------

-- ----------------------------
-- Table structure for ai_agents
-- ----------------------------
DROP TABLE IF EXISTS "public"."ai_agents";
CREATE TABLE "public"."ai_agents" (
  "id" int8 NOT NULL DEFAULT nextval('ai_agents_id_seq'::regclass),
  "uuid" varchar(32) COLLATE "pg_catalog"."default" NOT NULL,
  "name" varchar(128) COLLATE "pg_catalog"."default" NOT NULL,
  "description" text COLLATE "pg_catalog"."default",
  "tenant_id" int8,
  "status" int2 DEFAULT 1,
  "created_at" timestamp(6) DEFAULT now(),
  "updated_at" timestamp(6) DEFAULT now()
)
;
COMMENT ON COLUMN "public"."ai_agents"."id" IS 'Agent ID';
COMMENT ON COLUMN "public"."ai_agents"."uuid" IS '对外 Agent ID';
COMMENT ON COLUMN "public"."ai_agents"."name" IS 'Agent 名称（如 Research Agent）';
COMMENT ON COLUMN "public"."ai_agents"."description" IS '功能描述';
COMMENT ON COLUMN "public"."ai_agents"."tenant_id" IS '所属租户（可空=平台级）';
COMMENT ON COLUMN "public"."ai_agents"."status" IS '状态（0=停用 1=启用）';
COMMENT ON COLUMN "public"."ai_agents"."created_at" IS '创建时间';
COMMENT ON COLUMN "public"."ai_agents"."updated_at" IS '更新时间';
COMMENT ON TABLE "public"."ai_agents" IS 'Agent 定义（一类 Agent 的元信息）';

-- ----------------------------
-- Records of ai_agents
-- ----------------------------

-- ----------------------------
-- Table structure for ai_analysis_results
-- ----------------------------
DROP TABLE IF EXISTS "public"."ai_analysis_results";
CREATE TABLE "public"."ai_analysis_results" (
  "id" int8 NOT NULL DEFAULT nextval('ai_analysis_results_id_seq'::regclass),
  "paper_id" int8 NOT NULL,
  "mode" varchar(20) COLLATE "pg_catalog"."default",
  "content_level" int2 NOT NULL,
  "content_source" varchar(30) COLLATE "pg_catalog"."default",
  "method_summary" text COLLATE "pg_catalog"."default",
  "probe_match" bool DEFAULT false,
  "probe_confidence" "public"."ai_confidence_level",
  "key_formulas" jsonb,
  "optimization_method" varchar(255) COLLATE "pg_catalog"."default",
  "analyzed_at" timestamp(6) DEFAULT now(),
  "key_findings" text COLLATE "pg_catalog"."default",
  "usage_role" varchar(20) COLLATE "pg_catalog"."default",
  "implementation_or_application" text COLLATE "pg_catalog"."default",
  "probe_relation" text COLLATE "pg_catalog"."default",
  "research_question" text COLLATE "pg_catalog"."default",
  "methodology_type" varchar(100) COLLATE "pg_catalog"."default",
  "method_category" varchar(100) COLLATE "pg_catalog"."default",
  "method_components" jsonb,
  "research_design" text COLLATE "pg_catalog"."default",
  "key_innovation" text COLLATE "pg_catalog"."default",
  "limitations" text COLLATE "pg_catalog"."default",
  "evidence" jsonb
)
;
COMMENT ON COLUMN "public"."ai_analysis_results"."id" IS '自增 ID';
COMMENT ON COLUMN "public"."ai_analysis_results"."paper_id" IS '分析论文';
COMMENT ON COLUMN "public"."ai_analysis_results"."mode" IS '分析模式（probe_match/ai_suggest/landscape）';
COMMENT ON COLUMN "public"."ai_analysis_results"."content_level" IS '内容层级（L1-L4）';
COMMENT ON COLUMN "public"."ai_analysis_results"."content_source" IS '内容来源（method/optimization 等）';
COMMENT ON COLUMN "public"."ai_analysis_results"."method_summary" IS '方法总结';
COMMENT ON COLUMN "public"."ai_analysis_results"."probe_match" IS '是否匹配技术探针';
COMMENT ON COLUMN "public"."ai_analysis_results"."probe_confidence" IS '匹配置信度';
COMMENT ON COLUMN "public"."ai_analysis_results"."key_formulas" IS '关键公式';
COMMENT ON COLUMN "public"."ai_analysis_results"."optimization_method" IS '优化方法';
COMMENT ON COLUMN "public"."ai_analysis_results"."analyzed_at" IS '分析时间';
COMMENT ON COLUMN "public"."ai_analysis_results"."key_findings" IS '分支深挖关键发现（LLM 产出，持久化避免刷新丢失）';
COMMENT ON TABLE "public"."ai_analysis_results" IS '分支深挖分析结果（按论文+模式唯一）';

-- ----------------------------
-- Records of ai_analysis_results
-- ----------------------------

