-- ----------------------------

-- ----------------------------
-- Table structure for ai_user_security
-- ----------------------------
DROP TABLE IF EXISTS "public"."ai_user_security";
CREATE TABLE "public"."ai_user_security" (
  "id" int8 NOT NULL DEFAULT nextval('ai_user_security_id_seq'::regclass),
  "user_id" int8 NOT NULL,
  "mfa_enabled" bool DEFAULT false,
  "mfa_secret" varchar(64) COLLATE "pg_catalog"."default",
  "mfa_verified_at" timestamp(6),
  "login_fail_count" int4 DEFAULT 0,
  "locked_until" timestamp(6),
  "last_login_at" timestamp(6),
  "last_login_ip" varchar(64) COLLATE "pg_catalog"."default",
  "email_verified_at" timestamp(6),
  "phone_verified_at" timestamp(6),
  "created_at" timestamp(6) DEFAULT now(),
  "updated_at" timestamp(6) DEFAULT now()
)
;
COMMENT ON COLUMN "public"."ai_user_security"."id" IS '自增主键';
COMMENT ON COLUMN "public"."ai_user_security"."user_id" IS '关联用户（一对一）';
COMMENT ON COLUMN "public"."ai_user_security"."mfa_enabled" IS '是否开启多因素认证';
COMMENT ON COLUMN "public"."ai_user_security"."mfa_secret" IS 'MFA 密钥（加密存储，建议 KMS 托管）';
COMMENT ON COLUMN "public"."ai_user_security"."mfa_verified_at" IS 'MFA 启用验证时间';
COMMENT ON COLUMN "public"."ai_user_security"."login_fail_count" IS '连续登录失败次数（防暴力破解）';
COMMENT ON COLUMN "public"."ai_user_security"."locked_until" IS '账号锁定截止时间';
COMMENT ON COLUMN "public"."ai_user_security"."last_login_at" IS '最后登录时间';
COMMENT ON COLUMN "public"."ai_user_security"."last_login_ip" IS '最后登录 IP';
COMMENT ON COLUMN "public"."ai_user_security"."email_verified_at" IS '邮箱验证时间';
COMMENT ON COLUMN "public"."ai_user_security"."phone_verified_at" IS '手机验证时间';
COMMENT ON COLUMN "public"."ai_user_security"."created_at" IS '创建时间';
COMMENT ON COLUMN "public"."ai_user_security"."updated_at" IS '更新时间';
COMMENT ON TABLE "public"."ai_user_security" IS '账号安全状态：MFA/锁定/登录统计（防暴力破解）';

-- ----------------------------
-- Records of ai_user_security
-- ----------------------------

-- ----------------------------
-- Table structure for ai_user_sessions
-- ----------------------------
DROP TABLE IF EXISTS "public"."ai_user_sessions";
CREATE TABLE "public"."ai_user_sessions" (
  "id" int8 NOT NULL DEFAULT nextval('ai_user_sessions_id_seq'::regclass),
  "user_id" int8 NOT NULL,
  "session_id" varchar(36) COLLATE "pg_catalog"."default" NOT NULL,
  "refresh_token_hash" char(64) COLLATE "pg_catalog"."default" NOT NULL,
  "device_id" varchar(64) COLLATE "pg_catalog"."default",
  "device_name" varchar(128) COLLATE "pg_catalog"."default",
  "ip_address" varchar(64) COLLATE "pg_catalog"."default",
  "user_agent" varchar(500) COLLATE "pg_catalog"."default",
  "expires_at" timestamp(6) NOT NULL,
  "revoked_at" timestamp(6),
  "created_at" timestamp(6) DEFAULT now()
)
;
COMMENT ON COLUMN "public"."ai_user_sessions"."id" IS '自增主键';
COMMENT ON COLUMN "public"."ai_user_sessions"."user_id" IS '关联用户';
COMMENT ON COLUMN "public"."ai_user_sessions"."session_id" IS '会话唯一标识（对外）';
COMMENT ON COLUMN "public"."ai_user_sessions"."refresh_token_hash" IS 'Refresh Token SHA-256 哈希（不存原始 Token）';
COMMENT ON COLUMN "public"."ai_user_sessions"."device_id" IS '设备指纹/ID';
COMMENT ON COLUMN "public"."ai_user_sessions"."device_name" IS '设备名称（如 iPhone 15）';
COMMENT ON COLUMN "public"."ai_user_sessions"."ip_address" IS '登录 IP';
COMMENT ON COLUMN "public"."ai_user_sessions"."user_agent" IS '浏览器 UA';
COMMENT ON COLUMN "public"."ai_user_sessions"."expires_at" IS '会话过期时间';
COMMENT ON COLUMN "public"."ai_user_sessions"."revoked_at" IS '吊销时间';
COMMENT ON COLUMN "public"."ai_user_sessions"."created_at" IS '创建时间';
COMMENT ON TABLE "public"."ai_user_sessions" IS '登录会话：Access/Refresh 体系，支持多端登录与吊销';

-- ----------------------------
-- Records of ai_user_sessions
-- ----------------------------

-- ----------------------------
-- Table structure for ai_users
-- ----------------------------
DROP TABLE IF EXISTS "public"."ai_users";
CREATE TABLE "public"."ai_users" (
  "id" int8 NOT NULL DEFAULT nextval('ai_users_id_seq'::regclass),
  "uuid" varchar(32) COLLATE "pg_catalog"."default" NOT NULL,
  "username" varchar(64) COLLATE "pg_catalog"."default" NOT NULL,
  "email" varchar(255) COLLATE "pg_catalog"."default",
  "phone" varchar(20) COLLATE "pg_catalog"."default",
  "nickname" varchar(64) COLLATE "pg_catalog"."default",
  "avatar_url" varchar(500) COLLATE "pg_catalog"."default",
  "status" int2 DEFAULT 1,
  "tenant_id" int8,
  "preferences" jsonb,
  "created_at" timestamp(6) DEFAULT now(),
  "updated_at" timestamp(6) DEFAULT now(),
  "deleted_at" timestamp(6),
  "role" varchar(32) COLLATE "pg_catalog"."default" DEFAULT 'user'::character varying
)
;
COMMENT ON COLUMN "public"."ai_users"."id" IS '用户 ID（业务层不暴露）';
COMMENT ON COLUMN "public"."ai_users"."uuid" IS '对外用户 ID（usr_ 前缀，防遍历）';
COMMENT ON COLUMN "public"."ai_users"."username" IS '用户名（支持登录）';
COMMENT ON COLUMN "public"."ai_users"."email" IS '邮箱（支持登录 & 找回密码）';
COMMENT ON COLUMN "public"."ai_users"."phone" IS '手机号（支持短信登录）';
COMMENT ON COLUMN "public"."ai_users"."nickname" IS '展示昵称';
COMMENT ON COLUMN "public"."ai_users"."avatar_url" IS '头像 CDN 地址';
COMMENT ON COLUMN "public"."ai_users"."status" IS '状态（0=禁用 1=正常 2=待验证 3=锁定）';
COMMENT ON COLUMN "public"."ai_users"."tenant_id" IS '主租户（预留；多租户成员关系后续扩展）';
COMMENT ON COLUMN "public"."ai_users"."preferences" IS '用户偏好设置（主题/语言等 JSONB）';
COMMENT ON COLUMN "public"."ai_users"."created_at" IS '注册时间';
COMMENT ON COLUMN "public"."ai_users"."updated_at" IS '更新时间';
COMMENT ON COLUMN "public"."ai_users"."deleted_at" IS '软删除标记';
COMMENT ON COLUMN "public"."ai_users"."role" IS '角色：guest=游客 user=普通用户 admin=管理员';
COMMENT ON TABLE "public"."ai_users" IS '用户主表：纯粹的用户身份信息（登录/安全/偏好已拆分）';

-- ----------------------------
-- Records of ai_users
-- ----------------------------

